def path_distances(s):
    # full recursive returns map leaf->distance from node
    def rec(node):
        if node[0]=='leaf':
            return {node[1]:0.0}
        d={}
        for ch in node[1]:
            child_len=ch[2] if ch[2] is not None else 0.0
